  'x.mode': 'Analiz birimi', 'x.dec': 'Ondalık ayırıcı', 'x.loc': 'Weibull konumu a (hesaplananlar)', 'x.bounds': 'Kullanıcının sabitlediği sınırlar', 'x.methods': 'Seçilen yöntemler (seçenekler)',
