function drawPanel() { const p = $('panel'); if (!p) return; (S.tab === 'charts' ? tabCharts : S.tab === 'classes' ? tabClasses : S.tab === 'boot' ? tabBoot : tabParams)(p); }

/* plot navigator (shared component) + period switch, as in Plot & Stand Metrics */
