const wbOpts = () => S.wb.loc === 'user' ? { loc: 'user', a: (t => t === '' ? NaN : num(t))(String(S.wb.a).trim()) } : { loc: 'half-dmin' };
let RW = null;
function computeWb() { const sm = wbSummary(), o = wbOpts(); RW = wbChosen().map(m => D.runMethod(m.id, { type: 'summary', summary: sm }, o)); }
